SELECT * FROM torn_stock_virtual_batch
WHERE ledger_type = 'UNLIMITED_SHADOW'
  AND stocks_id = #{stocksId}
  AND primary_strategy = #{primaryStrategy}
  AND buy_rule_version = #{buyRuleVersion}
  AND batch_status IN ('ENTRY_PENDING', 'OPEN', 'DATA_STALE', 'EXIT_PENDING', 'DATA_STALE_EXIT')
  AND deleted = 0
ORDER BY id ASC
LIMIT 1
FOR UPDATE

SELECT * FROM torn_stock_virtual_batch WHERE ledger_type = 'REJECTED_OBSERVATION' AND batch_status = 'CANCELLED' AND deleted = 0 AND signal_event_id IN
#{signalEventId}
ORDER BY signal_event_id ASC, id ASC
